{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table Maplemonk.Healthy_Master_PNL_Fact_Items as select awb, coalesce(sc.marketplace, mc.marketplace) marketplace, coalesce(sc.channel_mapped, mc.marketing_channel) as channel, sc.order_id, reference_code, sku, sku_code, commonsku, product_id, COALESCE( DATE(sc.order_date), DATE(mc.date)) AS order_date, order_time, mrp_sales, QUANTITY, SAFE_CAST(mrp_sales AS FLOAT64) * SAFE_CAST(quantity AS FLOAT64) AS MRP, SAFE_CAST(sm.cogs AS FLOAT64) AS cogs, SAFE_CAST(sm.cogs AS FLOAT64) * SAFE_CAST(sc.quantity AS FLOAT64) AS SALE_COGS, CASE WHEN IFNULL(SAFE_CAST(returned_sales AS FLOAT64),0) > 0 THEN SAFE_CAST(sm.cogs AS FLOAT64) * SAFE_CAST(sc.quantity AS FLOAT64) ELSE 0 END AS return_cogs, CASE WHEN IFNULL(SAFE_CAST(cancelled_quantity AS FLOAT64),0) > 0 THEN SAFE_CAST(sm.cogs AS FLOAT64) * SAFE_CAST(sc.cancelled_quantity AS FLOAT64) ELSE 0 END AS cancelled_cogs, SAFE_CAST(GROSS_SALES_BEFORE_TAX AS FLOAT64) AS GROSS_SALES_BEFORE_TAX, SAFE_CAST(DISCOUNT AS FLOAT64) AS DISCOUNT, SAFE_CAST(tax AS FLOAT64) AS tax, CASE WHEN IFNULL(SAFE_CAST(returned_sales AS FLOAT64),0) > 0 THEN SAFE_CAST(tax AS FLOAT64) ELSE 0 END AS return_tax, SAFE_CAST(SHIPPING_PRICE AS FLOAT64) AS SHIPPING_PRICE, SAFE_CAST(SELLING_PRICE AS FLOAT64) AS SELLING_PRICE, CASE WHEN IFNULL(SAFE_CAST(cancelled_quantity AS FLOAT64),0) > 0 THEN SAFE_CAST(SELLING_PRICE AS FLOAT64) ELSE 0 END AS Cancelled_sales, coalesce(sm.product_title, sc.PRODUCT_NAME_FINAL) PRODUCT_NAME_FINAL, PRODUCT_CATEGORY, coalesce(sm.PRODUCT_TYPE, sc.product_type) PRODUCT_TYPE, FINAL_SHIPPING_STATUS, city, state, PAYMENT_GATEWAY, Payment_Mode, COURIER, returned_quantity, SAFE_CAST(returned_sales AS FLOAT64) AS returned_sales, SAFE_CAST(cancelled_quantity AS FLOAT64) AS cancelled_quantity, SAFE_CAST(shipment_cost AS FLOAT64) AS shipment_cost, SAFE_DIVIDE( IFNULL(SAFE_CAST(spend AS FLOAT64),0), COUNT(1) OVER ( PARTITION BY COALESCE(DATE(sc.order_date), DATE(mc.date)), COALESCE(sc.channel_mapped, mc.marketing_channel), COALESCE(sc.marketplace, mc.marketplace) ) ) AS spend, IFNULL(SAFE_CAST(ad_impressions AS FLOAT64),0) AS ad_impressions, IFNULL(SAFE_CAST(ad_clicks AS FLOAT64),0) AS ad_clicks, IFNULL(SAFE_CAST(ad_conversions AS FLOAT64),0) AS ad_conversions, SAFE_DIVIDE( IFNULL(SAFE_CAST(ad_sales AS FLOAT64),0), COUNT(1) OVER ( PARTITION BY COALESCE(DATE(sc.order_date), DATE(mc.date)), COALESCE(sc.channel_mapped, mc.marketing_channel), COALESCE(sc.marketplace, mc.marketplace) ) ) AS ad_sales from (select *, case when lower(channel) like any (\'%facebook%\',\'%fb%\',\'%meta%\',\'%insta%\',\'%ig%\') then \'FACEBOOK\' when lower(channel) like any (\'%google%\') then \'GOOGLE\' else upper(channel) end channel_mapped from maplemonk.healthymaster_wh_471810_sales_consolidated WHERE UPPER(marketplace) LIKE (\'%WEBSITE%\') ) sc full outer join ( select date ,case when lower(channel) like any (\'%facebook%\', \'%google%\') then \'WEBSITE D2C\' else upper(channel) end as Marketplace ,upper(channel) marketing_Channel, SUM(IFNULL(SAFE_CAST(spend AS FLOAT64),0)) AS spend, SUM(IFNULL(SAFE_CAST(impressions AS FLOAT64),0)) AS ad_impressions, SUM(IFNULL(SAFE_CAST(clicks AS FLOAT64),0)) AS ad_clicks, SUM(IFNULL(SAFE_CAST(conversions AS FLOAT64),0)) AS ad_conversions, SUM(IFNULL(SAFE_CAST(conversion_value AS FLOAT64),0)) AS ad_sales from healthymaster-wh-471810.maplemonk.healthymaster_wh_471810_MARKETING_CONSOLIDATED where channel in (\'GOOGLE\',\'FACEBOOK\') group by 1,2,3 ) mc on date(sc.order_Date) = date(MC.date) and lower(SC.channel_mapped)=lower(MC.marketing_channel) and upper(sc.marketplace) = upper(mc.marketplace) left join( select platform, Shopify_SKU, CAST(NULLIF(REPLACE(COGS, \',\', \'\'), \'#N/A\')AS float64) cogs, product_type, PRODUCT_TITLE from `maplemonk.gs_Updated_SKU_MASTER` where lower(platform) = \'shopify\' qualify row_number() over (partition by shopify_sku order by cast(cogs as float64) desc)=1) sm on UPPER(sc.SKU) = UPPER(sm.shopify_sku) LEFT JOIN( select distinct trackId, order_id, shipment_cost from `maplemonk.HM_vamaship_surface_tracking`) shc on sc.awb = shc.trackId ;",
                    "transaction": true
                }
            ) }}
